  function openWorld(id){const found=worlds.find(w=>w.id===id);if(!found)return;world=found;activeId=id;world.settings={...clone(DEFAULT_SETTINGS),...(world.settings||{})};if(!world.map)world.map={buildings:clone(BUILDINGS),unlockedAreas:['中心城区']};if(!Array.isArray(world.map.buildings))world.map.buildings=clone(BUILDINGS);if(!Array.isArray(world.residents))world.residents=[];if(!Array.isArray(world.relationships))world.relationships=[];if(!Array.isArray(world.families))world.families=[];if(!Array.isArray(world.logs))world.logs=[];if(!world.worldNow)world.worldNow=now();if(!world.lastRealAt)world.lastRealAt=now();$('scLobby').hidden=true;$('scCreatePanel').hidden=true;$('lrSpaceV2Directory').hidden=false;$('scWorld').hidden=false;$('scInterior').hidden=true;$('scWorldName').textContent=world.name;$('scWorldDate').textContent=dateLabel(world.worldNow);setTab('map');advanceTime();renderMap();renderLatestLogs();fillController();persist();startTicker()}
